// Validates the request: which screen to build, which operation to run and with which ids.
// GET (initial load) has no body; POST /view carries { view, op, id, wf, status, nav }.
const it = $input.first().json;
const body = it.body && typeof it.body === "object" && !Array.isArray(it.body) ? it.body : {};
const headers = it.headers ?? {};
let isGet = false;
try { isGet = $("Screen").first() !== undefined; } catch (e) { isGet = false; }

const VIEWS = ["panel", "workflows", "wf", "executions", "exec", "credentials", "people", "audit"];
const OPS = ["publish", "unpublish", "run", "retry", "retry_current", "stop", "delete_exec", "alerts_on", "alerts_off"];
const STATUSES = ["error", "success", "running", "waiting", "canceled", "crashed"];
const safeId = (v) => {
  const s = String(v ?? "").trim();
  return /^[A-Za-z0-9_-]{1,64}$/.test(s) ? s : "";
};

const id = safeId(body.id);
const op = OPS.includes(body.op) && id ? body.op : "";
const host = String(headers["x-forwarded-host"] ?? headers.host ?? "").split(",")[0].trim();

return [{
  json: {
    isGet,
    email: String(it.jwtPayload?.email ?? ""),
    role: String(it.jwtPayload?.role ?? ""),
    view: VIEWS.includes(body.view) ? body.view : "panel",
    op,
    id,
    wf: safeId(body.wf),
    status: STATUSES.includes(body.status) ? body.status : "",
    nav: Array.isArray(body.nav) ? body.nav.filter((s) => VIEWS.includes(s) && s !== "panel").slice(0, 4) : [],
    publicUrl: /^[A-Za-z0-9.-]+(:\d+)?$/.test(host) ? "https://" + host : "",
  },
}];

// Denied: not allowed by nc_apps, or not an admin of n8n Connect.
const message = $input.first().json.error?.message || "This app is for administrators only.";
return [{ json: { error: { code: "app_forbidden", message } } }];

// Turns the requested operation into one call to the n8n public API.
const API = "http://127.0.0.1:5678/api/v1";
const n = $("Normalize").first().json;
const OPS = {
  publish: ["POST", `/workflows/${n.id}/activate`],
  unpublish: ["POST", `/workflows/${n.id}/deactivate`],
  alerts_on: ["POST", `/workflows/${n.id}/activate`],
  alerts_off: ["POST", `/workflows/${n.id}/deactivate`],
  retry: ["POST", `/executions/${n.id}/retry`, { loadWorkflow: false }],
  retry_current: ["POST", `/executions/${n.id}/retry`, { loadWorkflow: true }],
  stop: ["POST", `/executions/${n.id}/stop`],
  delete_exec: ["DELETE", `/executions/${n.id}`],
};
const [method, path, body] = OPS[n.op];
return [{ json: { method, url: API + path, hasBody: Boolean(body), body: body ?? {} } }];

// Result of the operation as a short message for the phone.
const n = $("Normalize").first().json;
const r = $input.first().json ?? {};
const OK = {
  publish: "Workflow published",
  unpublish: "Workflow unpublished",
  alerts_on: "Error alerts turned on",
  alerts_off: "Error alerts turned off",
  stop: "Execution stopped",
  delete_exec: "Execution deleted",
  run: "Workflow started",
};
const SCOPE = {
  publish: "workflow:activate", unpublish: "workflow:deactivate", alerts_on: "workflow:activate",
  alerts_off: "workflow:deactivate", retry: "execution:retry", retry_current: "execution:retry",
  stop: "execution:stop", delete_exec: "execution:delete",
};

if (n.op === "run") {
  const err = r.error;
  const text = typeof err === "string" ? err : err?.description || err?.message || "";
  return [{ json: { opOk: !err, opMessage: err ? "Could not run: " + (text || "unknown error") : OK.run } }];
}

const code = Number(r.statusCode ?? 0);
if (code >= 200 && code < 300) {
  if (n.op === "retry" || n.op === "retry_current") {
    const b = r.body ?? {};
    return [{ json: { opOk: true, opMessage: `Retried: execution #${b.id ?? "?"} (${b.status ?? "started"})` } }];
  }
  return [{ json: { opOk: true, opMessage: OK[n.op] ?? "Done" } }];
}
let message;
if (code === 403) message = `Your n8n API key does not have the ${SCOPE[n.op]} permission. Create a key with all scopes (n8n → Settings → n8n API) and put it in the "n8n API" credential.`;
else if (code === 401) message = `Your n8n API key is not valid: check the "n8n API" credential.`;
else message = String(r.body?.message ?? r.error?.message ?? "") || `HTTP error ${code || "no response"}`;
return [{ json: { opOk: false, opMessage: message } }];

// One item per API call needed for the screens of this response (the HTTP node runs them all).
const API = "http://127.0.0.1:5678/api/v1";
const n = $("Normalize").first().json;
const since = DateTime.now().minus({ hours: 24 }).toUTC().toISO();
const need = new Set([n.view, ...n.nav]);
const wfId = n.wf || (n.view === "wf" ? n.id : "");

const calls = [
  ["workflows", "GET", "/workflows?limit=250&excludePinnedData=true&includeParentFolder=true"],
  ["running", "GET", "/executions?status=running&limit=50"],
  ["recent", "GET", "/executions?limit=40"],
  ["errors24", "GET", "/executions?status=error&limit=250&startedAfter=" + encodeURIComponent(since)],
  ["lastErrors", "GET", "/executions?status=error&limit=5"],
  ["insights", "GET", "/insights/summary"],
];
if (need.has("executions") && n.status && n.status !== "running") {
  calls.push(["execList", "GET", "/executions?limit=50&status=" + n.status]);
}
if (need.has("wf") && wfId) {
  calls.push(["wf", "GET", "/workflows/" + wfId + "?excludePinnedData=true"]);
  calls.push(["wfExecs", "GET", "/executions?limit=15&workflowId=" + wfId]);
}
if (n.view === "exec" && n.id) calls.push(["exec", "GET", "/executions/" + n.id + "?includeData=true"]);
if (need.has("credentials")) calls.push(["credentials", "GET", "/credentials?limit=250"]);
if (need.has("people")) {
  calls.push(["users", "GET", "/users?limit=100&includeRole=true"]);
  calls.push(["tags", "GET", "/tags?limit=250"]);
}
if (need.has("audit")) calls.push(["audit", "POST", "/audit", {}]);

return calls.map(([key, method, path, body]) => ({
  json: { key, method, url: API + path, hasBody: Boolean(body), body: body ?? {} },
}));

// The workflow list only carries folder ids. Folder names are cached in the workflow's
// static data; for unknown folders, read one workflow of each folder (its GET has the name).
const API = "http://127.0.0.1:5678/api/v1";
const plan = $("Plan fetch").all();
const res = $input.all();
const i = plan.findIndex((p) => p.json.key === "workflows");
const wfs = res[i]?.json?.body?.data ?? [];
const cache = $getWorkflowStaticData("global").folders ?? {};

const missing = {};
for (const w of wfs) {
  const fid = w.parentFolder?.id;
  if (fid && !cache[fid] && !missing[fid]) missing[fid] = w.id;
}
const calls = Object.entries(missing).slice(0, 10).map(([fid, wid]) => ({
  json: { fid, method: "GET", url: API + "/workflows/" + wid + "?excludePinnedData=true" },
}));
// Always one item so the chain continues: a cheap call when every name is cached.
if (!calls.length) calls.push({ json: { fid: "", method: "GET", url: API + "/tags?limit=1" } });
return calls;

// Builds the whole app spec (screens for this response) from the API answers.
// A POST answer replaces the spec, so it also returns the navigation that rebuilds the stack.
const TZ = "UTC"; // Set your time zone (IANA name, e.g. "America/New_York").
const VIEW_PATH = "n8n-connect/apps/n8n/view";
const ALERTS_NAME = "n8n Connect · App · n8n · Alerts";

const n = $("Normalize").first().json;
const SELF = $workflow.id;
const plan = $("Plan fetch").all();
const res = $("Fetch").all();
const R = {};
plan.forEach((p, i) => { R[p.json.key] = res[i]?.json ?? {}; });
const statusOf = (k) => Number(R[k]?.statusCode ?? 0);
const ok = (k) => (statusOf(k) >= 200 && statusOf(k) < 300 ? R[k].body : null);

// Folder names (cached across runs in static data).
const st = $getWorkflowStaticData("global");
st.folders = st.folders ?? {};
const fplan = $("Plan folders").all();
const fres = $("Fetch folders").all();
fplan.forEach((p, i) => {
  const pf = fres[i]?.json?.body?.parentFolder;
  if (p.json.fid && pf?.name) st.folders[p.json.fid] = pf.name;
});
const wfDetail = ok("wf");
if (wfDetail?.parentFolder?.id && wfDetail.parentFolder.name) st.folders[wfDetail.parentFolder.id] = wfDetail.parentFolder.name;

let opMessage = null;
try { opMessage = $("Op done").first().json.opMessage; } catch (e) { opMessage = null; }

// ---- helpers ----
const dt = (s) => (s ? DateTime.fromISO(s).setZone(TZ) : null);
const fmtDate = (s) => (dt(s) ? dt(s).toFormat("yyyy-MM-dd HH:mm") : "—");
const ago = (s) => {
  if (!s) return "";
  const sec = Math.max(0, Math.round((Date.now() - Date.parse(s)) / 1000));
  if (sec < 60) return sec + " s ago";
  const m = Math.round(sec / 60);
  if (m < 60) return m + " min ago";
  const h = Math.round(m / 60);
  if (h < 48) return h + " h ago";
  return Math.round(h / 24) + " days ago";
};
const dur = (a, b) => {
  if (!a || !b) return "";
  const ms = Date.parse(b) - Date.parse(a);
  if (!(ms >= 0)) return "";
  if (ms < 1000) return ms + " ms";
  const s = ms / 1000;
  if (s < 60) return s.toFixed(1) + " s";
  return Math.floor(s / 60) + " min " + Math.round(s % 60) + " s";
};
const msText = (ms) => (ms < 1000 ? Math.round(ms) + " ms" : (ms / 1000).toFixed(1) + " s");
const STATUS = {
  success: ["Success", "check_circle"], error: ["Error", "error"], crashed: ["Crashed", "warning"],
  canceled: ["Canceled", "stop"], running: ["Running", "play_arrow"], waiting: ["Waiting", "schedule"],
  new: ["Queued", "schedule"], unknown: ["Unknown", "info"],
};
const MODE = {
  trigger: "trigger", webhook: "webhook", manual: "manual", retry: "retry", integrated: "sub-workflow",
  internal: "internal", error: "error workflow", cli: "CLI", evaluation: "evaluation", chat: "chat", agent: "agent",
};
const typeLabel = (t) => String(t ?? "").split(".").pop();
const isTrigger = (t) => /trigger$/i.test(String(t)) || /\.(webhook|formTrigger|chatTrigger|mcpTrigger)$/i.test(String(t));
const TRIGGER = {
  webhook: "Webhook", scheduleTrigger: "Schedule", manualTrigger: "Manual", executeWorkflowTrigger: "Sub-workflow",
  formTrigger: "Form", chatTrigger: "Chat", errorTrigger: "Error", mcpTrigger: "MCP",
};
const triggerName = (t) => TRIGGER[typeLabel(t)] ?? typeLabel(t).replace(/Trigger$/, "");
const errText = (e) => {
  if (!e) return "";
  if (typeof e === "string") return e;
  const c = e.errorResponse?.content;
  const parts = [e.message, e.description, Array.isArray(c) ? c.join(" ") : typeof c === "string" ? c : ""]
    .map((x) => String(x ?? "").trim()).filter(Boolean);
  return [...new Set(parts)].join(" — ") || e.name || "Error without message";
};
const apiProblem = (k, what) => {
  const s = statusOf(k);
  if (s === 403) return `Your n8n API key does not have permission to ${what}. Create a key with all scopes (n8n → Settings → n8n API) and put it in the "n8n API" credential.`;
  if (s === 401) return `Your n8n API key is not valid: check the "n8n API" credential.`;
  return s ? `Could not ${what} (HTTP ${s}).` : `Could not ${what} (no response).`;
};
const view = (v, params = {}, loading = "Loading…") => ({ type: "submit", path: VIEW_PATH, body: { view: v, ...params }, loading });
const doOp = (op, params, confirm, loading = "Applying…") =>
  ({ type: "submit", path: VIEW_PATH, body: { op, ...params }, loading, ...(confirm ? { confirm } : {}) });
const short = (s, max = 160) => { const t = String(s ?? ""); return t.length > max ? t.slice(0, max - 1) + "…" : t; };
const subtitle = (text) => ({ type: "text", style: "subtitle", text });
const caption = (text) => ({ type: "text", style: "caption", text });

// Node map (`graph` component): the workflow's nodes and connections, without sticky notes.
const ICON_BY_TYPE = {
  webhook: "link", httpRequest: "cloud", code: "edit", function: "edit", set: "edit", if: "list", switch: "list",
  filter: "list", merge: "arrow_forward", respondToWebhook: "send", executeWorkflow: "play_arrow", dataTable: "list",
  wait: "timer", emailSend: "email", gmail: "email", discord: "send", telegram: "send", stopAndError: "error",
};
const nodeIcon = (t) => (isTrigger(t) ? "bolt" : ICON_BY_TYPE[typeLabel(t)] ?? "arrow_forward");
const AI_LABEL = { languageModel: "model", outputParser: "parser", textSplitter: "splitter", vectorStore: "store" };
// Label of output `i` of node `s` (`count` outputs saved), as n8n names it.
const outputLabel = (s, i, count) => {
  const t = typeLabel(s.type);
  const loop = t === "splitInBatches" && Number(s.typeVersion) >= 3;
  const regular = t === "if" || loop ? 2 : t === "switch" ? null : 1;
  const errorAt = s.onError === "continueErrorOutput" ? regular ?? Math.max(1, count - 1) : -1;
  if (i === errorAt) return "error";
  if (t === "if") return i === 0 ? "true" : "false";
  if (loop) return i === 0 ? "done" : "loop";
  if (errorAt > 0 && regular === 1) return "success";
  return count > 1 ? String(i) : undefined;
};
const flowGraph = (nodes, connections, decorate = () => ({})) => {
  const real = (nodes ?? []).filter((x) => !/\.stickyNote$/.test(String(x.type)));
  const byName = Object.fromEntries(real.map((x) => [x.name, x]));
  const edges = [];
  const seen = {};
  // One edge per pair of nodes: outputs that reach the same node share it ("true / false").
  const add = (from, to, extra) => {
    const key = from + "\u0000" + to;
    const old = seen[key];
    if (old) {
      if (extra.label && old.label !== extra.label) old.label = [old.label, extra.label].filter(Boolean).join(" / ");
      return;
    }
    seen[key] = { from, to, ...extra };
    edges.push(seen[key]);
  };
  for (const [src, outs] of Object.entries(connections ?? {})) {
    const s = byName[src];
    if (!s) continue;
    for (const [kind, branches] of Object.entries(outs ?? {})) {
      (branches ?? []).forEach((branch, i) => {
        for (const c of branch ?? []) {
          if (!byName[c.node]) continue;
          // AI sub-nodes (model, tools, memory) hang below their agent, as in n8n.
          if (kind !== "main") {
            const name = kind.replace(/^ai_/, "");
            add(c.node, src, { dashed: true, label: AI_LABEL[name] ?? name });
            continue;
          }
          const label = outputLabel(s, i, branches.length);
          add(src, c.node, label ? { label } : {});
        }
      });
    }
  }
  return {
    type: "graph",
    nodes: real.map((x) => ({ id: x.name, label: x.name, subtitle: typeLabel(x.type), icon: nodeIcon(x.type), ...(x.disabled ? { tone: "muted" } : {}), ...decorate(x) })),
    edges,
  };
};

// ---- data ----
const wfsAll = ok("workflows")?.data ?? [];
const wfName = {};
for (const w of wfsAll) wfName[w.id] = w.name;
const live = wfsAll.filter((w) => !w.isArchived);
const archived = wfsAll.filter((w) => w.isArchived);
const published = live.filter((w) => w.activeVersionId);
const running = (ok("running")?.data ?? []).filter((e) => e.workflowId !== SELF);
const recent = ok("recent")?.data ?? [];
const errors24 = ok("errors24")?.data ?? [];
const lastErrors = ok("lastErrors")?.data ?? [];
const insights = ok("insights");
const alertsWf = live.find((w) => w.name === ALERTS_NAME);
// Unpublishing these from the phone would lock you out of the app.
const isProtected = (w) => w.id === SELF || /^n8n Connect · (Core|App access)$/.test(w.name);
const folderOf = (w) => (w.parentFolder?.id ? st.folders[w.parentFolder.id] ?? "Folder" : "No folder");

const execItem = (e, nav, extra = {}) => {
  const [label, icon] = STATUS[e.status] ?? [e.status, "info"];
  return {
    title: wfName[e.workflowId] ?? "Workflow " + e.workflowId,
    subtitle: [label, ago(e.startedAt), dur(e.startedAt, e.stoppedAt), MODE[e.mode] ?? e.mode].filter(Boolean).join(" · "),
    icon,
    action: view("exec", { id: e.id, nav, ...extra }),
  };
};
const wfItem = (w, nav) => {
  const trig = [...new Set((w.nodes ?? []).filter((x) => isTrigger(x.type)).map((x) => triggerName(x.type)))];
  const state = w.isArchived ? "Archived" : w.activeVersionId ? "Published" : "Not published";
  return {
    title: w.name,
    subtitle: [state, (w.nodes?.length ?? 0) + ((w.nodes?.length ?? 0) === 1 ? " node" : " nodes"), trig.join(", ")].filter(Boolean).join(" · "),
    icon: w.isArchived ? "delete" : w.activeVersionId ? "check_circle" : "stop",
    action: view("wf", { id: w.id, wf: w.id, nav }),
  };
};

const screens = [];

// ---- panel ----
const panel = [];
if (!ok("workflows")) panel.push({ type: "banner", tone: "error", icon: "error", text: apiProblem("workflows", "list workflows") });
panel.push({
  type: "grid", columns: 2, components: [
    { type: "metric", label: "Workflows", value: String(live.length), icon: "list", caption: published.length + " published" },
    { type: "metric", label: "Running", value: String(running.length), icon: "play_arrow", caption: "executions now" },
    {
      type: "metric", label: "Errors 24 h", value: errors24.length + (errors24.length >= 250 ? "+" : ""), icon: "error",
      tone: errors24.length ? "error" : "success", caption: errors24.length ? "latest " + ago(errors24[0].startedAt) : "no errors",
    },
    insights
      ? {
        type: "metric", label: "Executions 7 days", value: String(insights.total?.value ?? 0), icon: "bolt",
        caption: "failures " + (Math.round((insights.failureRate?.value ?? 0) * 1000) / 10).toString() + " %",
      }
      : { type: "metric", label: "Recent", value: recent.length + (recent.length >= 40 ? "+" : ""), icon: "bolt", caption: "saved executions" },
  ],
});
panel.push(errors24.length
  ? { type: "banner", tone: "warning", icon: "warning", text: `${errors24.length}${errors24.length >= 250 ? "+" : ""} failed executions in the last 24 h.` }
  : { type: "banner", tone: "success", icon: "check_circle", text: "No errors in the last 24 h." });
panel.push(subtitle("Latest errors"));
panel.push(lastErrors.length
  ? { type: "list", items: lastErrors.map((e) => execItem(e, ["exec"])) }
  : caption("No failed executions saved."));
panel.push(subtitle("Sections"));
panel.push({
  type: "list", items: [
    { title: "Workflows", subtitle: `${live.length} workflows · ${published.length} published`, icon: "list", action: { type: "navigate", screen: "workflows" } },
    { title: "Executions", subtitle: "Latest executions, with filters", icon: "schedule", action: { type: "navigate", screen: "executions" } },
    { title: "Errors", subtitle: `${errors24.length} in the last 24 h`, icon: "error", action: view("executions", { status: "error", nav: ["executions"] }) },
    { title: "Credentials", subtitle: "Names and types, no secrets", icon: "lock", action: view("credentials", { nav: ["credentials"] }) },
    { title: "Users and tags", icon: "person", action: view("people", { nav: ["people"] }) },
    { title: "Security audit", subtitle: "n8n risk report", icon: "warning", action: view("audit", { nav: ["audit"] }, "Generating the report…") },
  ],
});
panel.push({
  type: "card", title: "Error alerts", icon: "notifications",
  subtitle: alertsWf
    ? alertsWf.activeVersionId ? "On: you get a phone alert when a workflow fails." : "Off."
    : `Can't find the workflow "${ALERTS_NAME}".`,
  components: alertsWf
    ? [alertsWf.activeVersionId
      ? { type: "button", label: "Turn off alerts", icon: "stop", style: "outlined", action: doOp("alerts_off", { id: alertsWf.id, view: "panel" }) }
      : { type: "button", label: "Turn on alerts", icon: "notifications", action: doOp("alerts_on", { id: alertsWf.id, view: "panel" }) }]
    : [],
});
if (n.publicUrl) panel.push({ type: "button", label: "Open n8n", icon: "link", style: "text", action: { type: "open_url", url: n.publicUrl } });
panel.push(caption("Updated at " + DateTime.now().setZone(TZ).toFormat("HH:mm") + ". Pull down to refresh."));
screens.push({ id: "panel", title: "n8n", components: panel });

// ---- workflows ----
const wfComps = [];
if (!ok("workflows")) wfComps.push({ type: "banner", tone: "error", icon: "error", text: apiProblem("workflows", "list workflows") });
const groups = {};
for (const w of live) (groups[folderOf(w)] ??= []).push(w);
const order = Object.keys(groups).sort((a, b) => (a === "No folder" ? 1 : b === "No folder" ? -1 : a.localeCompare(b, "en")));
wfComps.push(caption(`${live.length} workflows in ${order.length} groups · ${published.length} published`));
for (const g of order) {
  wfComps.push(subtitle(`${g} (${groups[g].length})`));
  wfComps.push({ type: "list", items: groups[g].sort((a, b) => a.name.localeCompare(b.name, "en")).map((w) => wfItem(w, ["workflows", "wf"])) });
}
if (archived.length) {
  wfComps.push(subtitle(`Archived (${archived.length})`));
  wfComps.push({ type: "list", items: archived.map((w) => wfItem(w, ["workflows", "wf"])) });
}
screens.push({ id: "workflows", title: "Workflows", components: wfComps });

// ---- executions ----
const FILTERS = [["", "All"], ["error", "Errors"], ["running", "Running"], ["waiting", "Waiting"], ["success", "Successful"], ["canceled", "Canceled"]];
const exComps = [{
  type: "grid", columns: 3, components: FILTERS.map(([s, label]) => ({
    type: "button", label, style: s === n.status ? "tonal" : "outlined",
    action: view("executions", { status: s, nav: ["executions"] }),
  })),
}];
let list;
if (n.status === "running") list = running;
else if (n.status) list = ok("execList")?.data ?? null;
else list = [...running, ...recent].sort((a, b) => Number(b.id) - Number(a.id)).slice(0, 50);
const filterLabel = (FILTERS.find(([s]) => s === n.status) ?? FILTERS[0])[1];
if (list === null) {
  exComps.push({ type: "banner", tone: "error", icon: "error", text: apiProblem("execList", "list executions") });
} else {
  exComps.push(caption(`${filterLabel}: ${list.length} ${list.length === 1 ? "execution" : "executions"} (most recent)`));
  exComps.push(list.length
    ? { type: "list", items: list.map((e) => execItem(e, ["executions", "exec"], n.status ? { status: n.status } : {})) }
    : caption("No executions match this filter."));
}
screens.push({ id: "executions", title: "Executions", components: exComps });

// ---- workflow detail ----
const need = new Set([n.view, ...n.nav]);
if (need.has("wf")) {
  const w = wfDetail;
  const wfNav = n.view === "wf" ? (n.nav.length ? n.nav : ["workflows", "wf"]) : n.nav.slice(0, n.nav.indexOf("wf") + 1);
  const comps = [];
  if (!w) {
    comps.push({ type: "banner", tone: "error", icon: "error", text: statusOf("wf") === 404 ? "This workflow no longer exists." : apiProblem("wf", "read the workflow") });
  } else {
    const nodes = w.nodes ?? [];
    const triggers = [...new Set(nodes.filter((x) => isTrigger(x.type)).map((x) => triggerName(x.type)))];
    const canRun = !w.isArchived && nodes.some((x) => /\.(executeWorkflowTrigger|manualTrigger)$/.test(x.type));
    const errWf = w.settings?.errorWorkflow;
    const execs = ok("wfExecs")?.data ?? [];
    comps.push({ type: "text", style: "title", text: w.name });
    if (w.isArchived) comps.push({ type: "banner", tone: "warning", icon: "warning", text: "Archived workflow." });
    comps.push({
      type: "details", items: [
        { label: "Status", value: w.isArchived ? "Archived" : w.activeVersionId ? "Published" : "Not published" },
        { label: "Folder", value: w.parentFolder?.name ?? "No folder" },
        { label: "Nodes", value: String(nodes.length) },
        { label: "Triggers", value: triggers.join(", ") || "None" },
        { label: "Last edited", value: fmtDate(w.updatedAt) },
        { label: "Created", value: fmtDate(w.createdAt) },
        { label: "Error workflow", value: errWf ? wfName[errWf] ?? errWf : "None" },
        { label: "Tags", value: (w.tags ?? []).map((t) => t.name).join(", ") || "—" },
        { label: "ID", value: w.id },
      ],
    });
    const buttons = [];
    if (!w.isArchived && !isProtected(w)) {
      buttons.push(w.activeVersionId
        ? {
          type: "button", label: "Unpublish", icon: "stop", style: "outlined",
          action: doOp("unpublish", { id: w.id, wf: w.id, view: "wf", nav: wfNav }, { title: "Unpublish", message: `Unpublish "${w.name}"? Its triggers will stop working.`, confirmLabel: "Unpublish" }),
        }
        : {
          type: "button", label: "Publish", icon: "play_arrow",
          action: doOp("publish", { id: w.id, wf: w.id, view: "wf", nav: wfNav }, { title: "Publish", message: `Publish "${w.name}"?`, confirmLabel: "Publish" }),
        });
    }
    if (canRun) {
      buttons.push({
        type: "button", label: "Run now", icon: "bolt", style: "tonal",
        action: doOp("run", { id: w.id, wf: w.id, view: "wf", nav: wfNav }, { title: "Run", message: `Run "${w.name}" now?`, confirmLabel: "Run" }, "Starting…"),
      });
    }
    buttons.push({ type: "button", label: "Refresh", icon: "refresh", style: "text", action: view("wf", { id: w.id, wf: w.id, nav: wfNav }) });
    if (n.publicUrl) buttons.push({ type: "button", label: "Open in n8n", icon: "link", style: "text", action: { type: "open_url", url: `${n.publicUrl}/workflow/${w.id}` } });
    comps.push({ type: "grid", columns: 2, components: buttons });
    if (isProtected(w)) comps.push(caption("Used by n8n Connect: it cannot be unpublished from the app."));
    if (canRun && !w.activeVersionId && nodes.some((x) => /\.executeWorkflowTrigger$/.test(x.type))) {
      comps.push(caption("To run it from here it must be published."));
    }
    comps.push(subtitle("Latest executions"));
    comps.push(execs.length
      ? { type: "list", items: execs.map((e) => execItem(e, [...wfNav, "exec"], { wf: w.id })) }
      : caption(ok("wfExecs") ? "No saved executions." : apiProblem("wfExecs", "list its executions")));
    const graph = flowGraph(nodes, w.connections);
    comps.push(subtitle(`Workflow map (${graph.nodes.length} nodes)`));
    comps.push(graph);
  }
  screens.push({ id: "wf", title: "Workflow", components: comps });
}

// ---- execution detail ----
if (n.view === "exec") {
  const x = ok("exec");
  const comps = [];
  if (!x) {
    comps.push({ type: "banner", tone: "error", icon: "error", text: !n.id ? "No execution specified." : statusOf("exec") === 404 ? "This execution no longer exists." : apiProblem("exec", "read the execution") });
  } else {
    const rd = x.data?.resultData ?? {};
    const last = rd.lastNodeExecuted;
    const lastRuns = last ? rd.runData?.[last] ?? [] : [];
    const err = (lastRuns.length ? lastRuns[lastRuns.length - 1]?.error : null) ?? rd.error;
    const [label] = STATUS[x.status] ?? [x.status];
    const parentNav = n.nav.slice(0, Math.max(0, n.nav.indexOf("exec")));
    const execNav = n.nav.length ? n.nav : ["exec"];
    const ctx = { id: x.id, view: "exec", nav: execNav, ...(n.wf ? { wf: n.wf } : {}), ...(n.status ? { status: n.status } : {}) };
    comps.push({ type: "text", style: "title", text: x.workflowData?.name ?? wfName[x.workflowId] ?? "Workflow " + x.workflowId });
    if (x.status === "error" || x.status === "crashed") {
      comps.push({ type: "banner", tone: "error", icon: "error", text: (last ? `Failed at "${last}": ` : "") + short(errText(err) || "no details", 400) });
    }
    if (x.dataTooLargeToDisplay) comps.push({ type: "banner", tone: "info", icon: "info", text: "This execution's data is too large to display." });
    comps.push({
      type: "details", items: [
        { label: "Status", value: label },
        { label: "Mode", value: MODE[x.mode] ?? x.mode },
        { label: "Started", value: fmtDate(x.startedAt) },
        { label: "Ended", value: fmtDate(x.stoppedAt) },
        { label: "Duration", value: dur(x.startedAt, x.stoppedAt) || "—" },
        ...(x.retryOf ? [{ label: "Retry of", value: "#" + x.retryOf }] : []),
        ...(x.retrySuccessId ? [{ label: "Retried successfully as", value: "#" + x.retrySuccessId }] : []),
        { label: "ID", value: "#" + x.id },
      ],
    });
    const buttons = [];
    if (["error", "crashed", "canceled"].includes(x.status)) {
      buttons.push({
        type: "button", label: "Retry", icon: "refresh",
        action: doOp("retry", ctx, { title: "Retry", message: "Retry with the workflow version that was used then?", confirmLabel: "Retry" }, "Retrying…"),
      });
      buttons.push({
        type: "button", label: "With current version", icon: "refresh", style: "tonal",
        action: doOp("retry_current", ctx, { title: "Retry", message: "Retry with the current workflow version?", confirmLabel: "Retry" }, "Retrying…"),
      });
    }
    if (["running", "waiting", "new"].includes(x.status)) {
      buttons.push({
        type: "button", label: "Stop", icon: "stop",
        action: doOp("stop", ctx, { title: "Stop", message: "Stop this execution?", confirmLabel: "Stop" }),
      });
    }
    buttons.push({ type: "button", label: "View workflow", icon: "list", style: "outlined", action: view("wf", { id: x.workflowId, wf: x.workflowId, nav: ["workflows", "wf"] }) });
    buttons.push({ type: "button", label: "Refresh", icon: "refresh", style: "text", action: view("exec", { id: x.id, nav: execNav, ...(n.wf ? { wf: n.wf } : {}), ...(n.status ? { status: n.status } : {}) }) });
    if (n.publicUrl) buttons.push({ type: "button", label: "Open in n8n", icon: "link", style: "text", action: { type: "open_url", url: `${n.publicUrl}/workflow/${x.workflowId}/executions/${x.id}` } });
    if (x.status !== "running") {
      const back = parentNav.includes("wf")
        ? { view: "wf", nav: parentNav }
        : { view: "executions", nav: ["executions"], ...(n.status ? { status: n.status } : {}) };
      buttons.push({
        type: "button", label: "Delete", icon: "delete", style: "text",
        action: doOp("delete_exec", { ...back, id: x.id, ...(n.wf ? { wf: n.wf } : {}) }, { title: "Delete execution", message: "Delete this execution and its data? This cannot be undone.", confirmLabel: "Delete" }),
      });
    }
    comps.push({ type: "grid", columns: 2, components: buttons });
    const runs = Object.entries(rd.runData ?? {}).map(([name, arr]) => {
      const t = arr[arr.length - 1] ?? {};
      const items = (t.data?.main ?? []).reduce((a, o) => a + (Array.isArray(o) ? o.length : 0), 0);
      const failed = t.executionStatus === "error" || Boolean(t.error);
      return {
        name, start: t.startTime ?? 0, failed,
        ms: arr.reduce((a, r) => a + (r.executionTime ?? 0), 0),
        text: [failed ? "Error" : "Success", msText(arr.reduce((a, r) => a + (r.executionTime ?? 0), 0)), items + (items === 1 ? " item" : " items"), arr.length > 1 ? arr.length + " runs" : ""].filter(Boolean).join(" · "),
        badge: items + (items === 1 ? " item" : " items"),
      };
    }).sort((a, b) => a.start - b.start);
    const runByName = Object.fromEntries(runs.map((r) => [r.name, r]));
    const wd = x.workflowData ?? {};
    if ((wd.nodes ?? []).length) {
      const graph = flowGraph(wd.nodes, wd.connections, (node) => {
        const r = runByName[node.name];
        if (!r) return { tone: "muted" };
        return { tone: r.failed ? "error" : "success", badge: r.failed ? "error" : r.badge };
      });
      comps.push(subtitle(`Workflow map (${graph.nodes.length} nodes)`));
      comps.push(graph);
      comps.push(caption("Colored border: ran · red: failed · faded: did not run."));
    }
    if (runs.length) {
      comps.push(subtitle(`Executed nodes (${runs.length})`));
      comps.push({ type: "list", items: runs.map((r) => ({ title: r.name, subtitle: r.failed && r.name === last && err ? short(errText(err), 200) : r.text, icon: r.failed ? "error" : "check_circle" })) });
    }
  }
  screens.push({ id: "exec", title: "Execution", components: comps });
}

// ---- credentials ----
if (need.has("credentials")) {
  const c = ok("credentials");
  const comps = [];
  if (!c) comps.push({ type: "banner", tone: "warning", icon: "lock", text: apiProblem("credentials", "list credentials") });
  else {
    const creds = (c.data ?? []).sort((a, b) => String(a.name).localeCompare(String(b.name), "en"));
    comps.push(caption(`${creds.length} credentials. n8n never returns their secrets.`));
    comps.push({ type: "list", items: creds.map((x) => ({ title: x.name, subtitle: x.type + (x.updatedAt ? " · edited " + ago(x.updatedAt) : ""), icon: "lock" })) });
  }
  screens.push({ id: "credentials", title: "Credentials", components: comps });
}

// ---- users and tags ----
if (need.has("people")) {
  const comps = [subtitle("Users")];
  const u = ok("users");
  if (!u) comps.push({ type: "banner", tone: "warning", icon: "person", text: apiProblem("users", "list users") });
  else {
    const ROLE = { "global:owner": "owner", "global:admin": "admin", "global:member": "member" };
    comps.push({
      type: "list", items: (u.data ?? []).map((x) => ({
        title: [x.firstName, x.lastName].filter(Boolean).join(" ") || x.email,
        subtitle: [x.email, ROLE[x.role] ?? x.role, x.isPending ? "invitation pending" : "", x.mfaEnabled ? "2FA enabled" : "no 2FA"].filter(Boolean).join(" · "),
        icon: "person",
      })),
    });
  }
  comps.push(subtitle("Tags"));
  const t = ok("tags");
  if (!t) comps.push({ type: "banner", tone: "warning", icon: "info", text: apiProblem("tags", "list tags") });
  else comps.push((t.data ?? []).length ? { type: "list", items: t.data.map((x) => ({ title: x.name, icon: "star" })) } : caption("No tags."));
  screens.push({ id: "people", title: "Users and tags", components: comps });
}

// ---- security audit ----
if (need.has("audit")) {
  const a = ok("audit");
  const comps = [];
  const REPORT = {
    "Credentials Risk Report": "Credentials", "Database Risk Report": "Database", "Filesystem Risk Report": "File system",
    "Nodes Risk Report": "Nodes", "Instance Risk Report": "Instance",
  };
  const SECTION = {
    "Credentials not used in any workflow": "Credentials not used in any workflow",
    "Credentials not used in any active workflow": "Credentials unused by active workflows",
    "Credentials not used in recently executed workflows": "Credentials unused by recent executions",
    'Expressions in "Execute Query" fields in SQL nodes': "Expressions in SQL queries",
    'Expressions in "Query Parameters" fields in SQL nodes': "Expressions in SQL parameters",
    'Unused "Query Parameters" fields in SQL nodes': "Unused SQL parameters",
    "Nodes that interact with the filesystem": "Nodes that access the file system",
    "Official risky nodes": "Risky official nodes",
    "Community nodes": "Community nodes",
    "Custom nodes": "Custom nodes",
    "Unprotected webhooks in instance": "Unauthenticated webhooks",
    "Outdated instance": "Outdated n8n version",
    "Security settings": "Security settings",
  };
  const locName = (l) => l.kind === "credential" ? l.name : l.kind === "node" ? `${l.workflowName} / ${l.nodeName}` : l.nodeType ?? l.name ?? "";
  if (a === null) comps.push({ type: "banner", tone: "error", icon: "error", text: apiProblem("audit", "generate the audit") });
  else if (Array.isArray(a) || !Object.keys(a).length) comps.push({ type: "banner", tone: "success", icon: "check_circle", text: "The audit found no risks." });
  else {
    comps.push(caption("Report generated by n8n's security checks."));
    for (const [name, report] of Object.entries(a)) {
      comps.push({
        type: "card", title: REPORT[name] ?? name, icon: "warning",
        components: [{
          type: "list", items: (report.sections ?? []).map((s) => {
            let sub;
            if (s.nextVersions?.length) sub = `${s.nextVersions.length} newer ${s.nextVersions.length === 1 ? "version" : "versions"} (latest: ${s.nextVersions[0].name})` + (s.nextVersions.some((v) => v.hasSecurityFix) ? ", with security fixes." : ".");
            else if (s.settings?.features) sub = Object.entries(s.settings.features).map(([k, v]) => `${k}: ${v ? "yes" : "no"}`).join(" · ");
            else {
              const locs = s.location ?? [];
              sub = `${locs.length} ${locs.length === 1 ? "item" : "items"}` + (locs.length ? ": " + locs.slice(0, 4).map(locName).join(", ") + (locs.length > 4 ? "…" : "") : "");
            }
            return { title: SECTION[s.title] ?? s.title, subtitle: short(sub, 220), icon: "warning" };
          }),
        }],
      });
    }
  }
  screens.push({ id: "audit", title: "Audit", components: comps });
}

// ---- response ----
const spec = { schema: 1, title: "n8n", start: "panel", screens };
if (n.isGet) return [{ json: { status: 200, body: spec } }];
const has = (id) => screens.some((s) => s.id === id);
const DEFAULT_NAV = { workflows: ["workflows"], wf: ["workflows", "wf"], executions: ["executions"], exec: ["exec"], credentials: ["credentials"], people: ["people"], audit: ["audit"] };
const nav = (n.nav.length ? n.nav : DEFAULT_NAV[n.view] ?? []).filter(has);
const body = { spec };
if (nav.length) body.screen = nav[0];
if (nav.length > 1) body.actions = nav.slice(1).map((s) => ({ type: "navigate", screen: s }));
if (opMessage) body.message = opMessage;
return [{ json: { status: 200, body } }];
